1	/* ===== Đi dạo: nạp mô hình người có xương (public/people/p<k>.glb) và một nhân vật đang diễn =====
2	   - stRigLoad(k): import() động GLTFLoader + SkeletonUtils (chunk riêng, trang thường không tải), nạp p<k>.glb một lần, nhớ đệm theo k.
3	     Lỗi bất kỳ (mạng, file hỏng, thiếu đoạn) → console.warn một lần cho mô hình đó, trả null, không thử lại trong phiên; promise không bao giờ bị từ chối.
4	   - stRigSource: chuẩn hóa cảnh đã nạp: lớp 1 (không vào phản chiếu nước), không đổ / nhận bóng, tắt frustumCulled (hộp bao theo tư thế gốc sai khi diễn),
5	     vật liệu metalness 0, roughness 0.85; mảnh alpha (alphaMode MASK) giữ alphaTest, không trộn trong suốt. Tốc độ tự nhiên từng đoạn đọc từ extras.speed.
6	   - StRig: một bản sao (SkeletonUtils.clone, dùng chung geometry / texture / vật liệu với nguồn) + AnimationMixer riêng.
7	     pose(): trọng số đích từ stClipMix (anim.ts), làm mượt về đích với hằng thời gian anim.fade; walk / jog / sprint đồng pha bằng một pha chung 0–1
8	     (đặt action.time = pha × thời lượng đoạn, timeScale 0 để mixer không tự tua); photo LoopOnce + clampWhenFinished, phát lại từ đầu mỗi lần chuyển sang dáng chụp ảnh.
9	     dt kẹp [0, stroll.dtMax] (tab ẩn rồi quay lại không làm nhảy pha). Không cấp phát mỗi khung (D-018).
10	   - Mô hình: mét, chân ở y = 0, mặt hướng +X (như hình khối), xương Rocketbox (Bip01_*). docs/superpowers/specs/2026-11-12-nguoi-di-dao-that-design.md §5, §7 */
11	import * as THREE from 'three';
12	import { CONFIG } from '../../config';
13	import { ST_CLIPS, stClipMix, type StClipMix } from './anim';
14	
15	const A = CONFIG.stroll.anim, NC = ST_CLIPS.length;
16	const ST_LOCO0 = 1, ST_LOCO1 = 3, ST_PHOTO = 4;   // chỉ số trong ST_CLIPS: walk..sprint, photo (idle = 0)
17	
18	export interface StRigSource {
19	  scene: THREE.Object3D;                                   // cảnh gốc (không thêm vào scene; chỉ để sao chép)
20	  clips: THREE.AnimationClip[];                            // 5 đoạn theo thứ tự ST_CLIPS
21	  natural: Float32Array;                                   // tốc độ tự nhiên từng đoạn theo ST_CLIPS, m/s (idle / photo = 0)
22	  height: number;                                          // chiều cao tư thế đứng, m (0 nếu file không ghi)
23	  clone: (o: THREE.Object3D) => THREE.Object3D;            // SkeletonUtils.clone (test truyền bản giả)
24	}
25	
26	/* Chuẩn hóa cảnh + đoạn đã nạp thành nguồn dùng chung. speeds: tên đoạn → m/s. Thiếu đoạn nào thì ném lỗi (stRigLoad bắt, trả null) */
27	export function stRigSource(scene: THREE.Object3D, clips: THREE.AnimationClip[], speeds: Record<string, number>, height: number, clone: (o: THREE.Object3D) => THREE.Object3D): StRigSource {
28	  const out: THREE.AnimationClip[] = [], natural = new Float32Array(NC);
29	  for (let i = 0; i < NC; i++) {
30	    const c = clips.find(x => x.name === ST_CLIPS[i]);
31	    if (!c) throw new Error(`thiếu đoạn ${ST_CLIPS[i]}`);
32	    out.push(c);
33	    natural[i] = Math.max(0, Number(speeds[ST_CLIPS[i]]) || 0);
34	  }
35	  scene.traverse((o) => {
36	    o.layers.set(1);
37	    const m = o as THREE.Mesh;
38	    if (!m.isMesh) return;
39	    m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false;
40	    const mats = Array.isArray(m.material) ? m.material : [m.material];
41	    for (const mat of mats) {
42	      const s = mat as THREE.MeshStandardMaterial;
43	      if (s.isMeshStandardMaterial) { s.metalness = 0; s.roughness = 0.85; }
44	      if (s.alphaTest > 0) s.transparent = false;   // MASK: cắt theo alphaTest, không trộn trong suốt (không cần sắp thứ tự)
45	    }
46	  });
47	  return { scene, clips: out, natural, height: height > 0 ? height : 0, clone };
48	}
49	
50	const cache = new Map<number, Promise<StRigSource | null>>();
51	
52	/* Nạp mô hình k (nhớ đệm). Không bao giờ ném / từ chối: lỗi → warn một lần, null */
53	export function stRigLoad(model: number): Promise<StRigSource | null> {
54	  let p = cache.get(model);
55	  if (p) return p;
56	  p = (async () => {
57	    try {
58	      const path = A.models[model];
59	      if (!path) throw new Error('không có mô hình số này');
60	      const [{ GLTFLoader }, SU] = await Promise.all([import('three/addons/loaders/GLTFLoader.js'), import('three/addons/utils/SkeletonUtils.js')]);
61	      const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + path);
62	      const speeds: Record<string, number> = {};
63	      const json = gltf.parser.json as { animations?: { name?: string; extras?: { speed?: number } }[] };   // AnimationClip không giữ extras: đọc từ JSON gốc
64	      for (const a of json.animations || []) if (a.name) speeds[a.name] = Number(a.extras?.speed) || 0;
65	      return stRigSource(gltf.scene, gltf.animations, speeds, Number(gltf.scene.userData?.height) || 0, SU.clone);
66	    } catch (e) {
67	      console.warn(`Đi dạo: không nạp được mô hình người ${model}, dùng hình khối`, e);
68	      return null;
69	    }
70	  })();
71	  cache.set(model, p);
72	  return p;
73	}
74	
75	/* Một nhân vật đang diễn: bản sao của nguồn + mixer riêng */
76	export class StRig {
77	  readonly root: THREE.Object3D;
78	  readonly src: StRigSource;
79	  readonly mixer: THREE.AnimationMixer;
80	  readonly actions: THREE.AnimationAction[] = [];
81	  readonly w = new Float32Array(NC);    // trọng số đang dùng (đã làm mượt), tổng = 1
82	  rate = 1;                             // hệ số tua đoạn di chuyển đang dùng
83	  phase = 0;                            // pha chung 0–1 của walk / jog / sprint
84	  private readonly mix: StClipMix = { w: new Float32Array(NC), rate: 1, loco: false };
85	  private fresh = true;                 // lần pose đầu: đặt thẳng trọng số đích, không làm mượt
86	  private photo = false;                // khung trước đang ở dáng chụp ảnh
87	
88	  constructor(src: StRigSource) {
89	    this.src = src;
90	    this.root = src.clone(src.scene);
91	    this.root.name = 'stroll-rig';
92	    this.mixer = new THREE.AnimationMixer(this.root);
93	    for (let i = 0; i < NC; i++) {
94	      const a = this.mixer.clipAction(src.clips[i]);
95	      if (i === ST_PHOTO) { a.setLoop(THREE.LoopOnce, 1); a.clampWhenFinished = true; }
96	      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.timeScale = 0;   // thời gian do pha chung đặt
97	      a.enabled = false; a.setEffectiveWeight(0); a.play();
98	      this.actions.push(a);
99	    }
100	  }
101	
102	  /* Mỗi khung: dáng + tốc độ mặt bằng (m/s) + dt (s) → trọng số, pha, mixer.update */
103	  pose(pose: number, speed: number, dt: number): void {
104	    const d = dt > 0 ? (dt < CONFIG.stroll.dtMax ? dt : CONFIG.stroll.dtMax) : 0;   // NaN / âm → 0
105	    const mix = this.mix, w = this.w, acts = this.actions, clips = this.src.clips;
106	    stClipMix(pose, speed, this.src.natural, mix);
107	    const toPhoto = mix.w[ST_PHOTO] === 1;
108	    if (toPhoto && !this.photo) acts[ST_PHOTO].reset();   // chuyển sang chụp ảnh: giơ máy lại từ đầu
109	    this.photo = toPhoto;
110	    const k = this.fresh ? 1 : 1 - Math.exp(-d / A.fade);
111	    this.fresh = false;
112	    for (let i = 0; i < NC; i++) w[i] += (mix.w[i] - w[i]) * k;
113	    if (mix.loco) this.rate = mix.rate;   // đang rời nhóm di chuyển: giữ nhịp cũ trong lúc mờ dần
114	    let lw = 0, dur = 0;
115	    for (let i = ST_LOCO0; i <= ST_LOCO1; i++) { lw += w[i]; dur += w[i] * clips[i].duration; }
116	    if (lw > 1e-4 && dur > 1e-6) {
117	      const p = this.phase + d * this.rate / (dur / lw);   // chu kỳ của hỗn hợp = trung bình thời lượng theo trọng số
118	      this.phase = p - Math.floor(p);
119	    }
120	    for (let i = 0; i < NC; i++) {
121	      const a = acts[i], on = w[i] > 1e-4;
122	      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.time = this.phase * clips[i].duration;
123	      if (on !== a.enabled) a.enabled = on;   // đoạn không trọng số: mixer bỏ qua, không tính
124	      a.setEffectiveWeight(on ? w[i] : 0);
125	    }
126	    this.mixer.update(d);
127	  }
128	
129	  /* Đặt lại như vừa tạo: lần pose kế đặt thẳng trọng số đích */
130	  reset(): void { this.fresh = true; this.photo = false; this.phase = 0; this.w.fill(0); }
131	
132	  /* Gỡ khỏi nhóm và bỏ mixer; geometry / texture / vật liệu thuộc nguồn dùng chung nên không dispose */
133	  dispose(): void {
134	    this.mixer.stopAllAction();
135	    this.mixer.uncacheRoot(this.root);
136	    this.root.removeFromParent();
137	  }
138	}
