1	/* ===== Đi dạo: nhân vật hiển thị (mình + tối đa 4 người khác) =====
2	   Nhóm 'stroll-people' (THREE.Group): mỗi slot đi dạo (đi một mình dùng 0) hiện bằng một nhân vật có xương (rig.ts, mô hình theo stModelFor: mình luôn 0, người khác 1 + slot mod 4).
3	   Mô hình chưa nạp xong hoặc nạp lỗi: slot hiện bằng hình khối (blocky.ts, InstancedMesh con của nhóm) nên lỗi mạng không bao giờ làm mất nhân vật.
4	   - Nạp lười: lần đầu một slot đang hiện cần mô hình k thì gọi bộ nạp (stRigLoad, test thay bằng __setLoader); kết quả chỉ vào bộ đệm sources[k].
5	     Bản sao chỉ tạo trong vòng khung (stPlace) cho slot đang hiện và đúng mô hình lúc đó, nên kết quả về muộn (slot đã đổi chủ, đã trống, đã rời chế độ) không bao giờ gắn nhầm (Review Focus 2).
6	   - Slot đổi chủ / đổi mô hình / clear(): gỡ bản sao khỏi nhóm, bỏ mixer (StRig.dispose; geometry / texture của nguồn dùng chung giữ lại).
7	   - dt cho mixer: mình nhận dt của bước chuyển động qua setSelf; người khác dùng hiệu nowMs giữa hai lần update; StRig kẹp ≤ stroll.dtMax (Review Focus 3).
8	   - Người khác nội suy bằng ExTrack như remote.ts (trường thứ 6 chở pose, lấy mẫu bậc thang step = true); slot đổi chủ thì xóa mẫu và ẩn tới mẫu đầu.
9	   Lớp 1, không đổ bóng (rig.ts, blocky.ts). build() chỉ dựng (lần đầu gọi, không lúc dựng cảnh), bên gọi tự thêm vào scene. Không cấp phát mỗi khung (D-018). */
10	import * as THREE from 'three';
11	import { CONFIG } from '../../config';
12	import { ExTrack, type ExPose } from '../multi/interp';
13	import type { Flyer } from '../multi/protocol';
14	import { ST_POSE_WALK, ST_POSE_RUN, type StState } from './motion';
15	import { stModelFor } from './anim';
16	import { stBlocky } from './blocky';
17	import { stRigLoad, StRig, type StRigSource } from './rig';
18	
19	export { stAvatarVar } from './blocky';
20	
21	const M = CONFIG.explore.multi, C = CONFIG.stroll, N = M.stroll.slots;
22	
23	interface StSlot {
24	  who: 0 | 1 | 2;             // 0 trống, 1 mình, 2 người khác
25	  name: string | null;        // tên người khác (từ sync); null = không có
26	  track: ExTrack;
27	  pose: ExPose;               // đệm lấy mẫu (bank chở pose)
28	  st: { x: number; y: number; z: number; yaw: number; pose: number };   // trạng thái trả cho slotState
29	  live: boolean;              // đang hiện
30	  rig: StRig | null;          // nhân vật có xương đang gắn (null: hình khối)
31	  model: number;              // mô hình của rig
32	}
33	
34	const slots: StSlot[] = Array.from({ length: N }, () => ({
35	  who: 0 as const, name: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
36	  st: { x: 0, y: 0, z: 0, yaw: 0, pose: 0 }, live: false, rig: null, model: -1
37	}));
38	let group: THREE.Group | null = null, me = -1, lastNow = -1;
39	
40	/* Bộ đệm mô hình: undefined = chưa có kết quả, null = nạp lỗi (giữ hình khối, không thử lại), còn lại = nguồn */
41	let loader: (model: number) => Promise<StRigSource | null> = stRigLoad;
42	let sources: (StRigSource | null | undefined)[] = [];
43	let asked = new Set<number>();
44	let gen = 0;   // thế hệ bộ nạp: __setLoader tăng để kết quả của bộ nạp cũ bị bỏ
45	
46	/* Nguồn của mô hình k nếu đã nạp xong; chưa thì bắt đầu nạp (một lần) và trả null. Không ném */
47	function stNeed(model: number): StRigSource | null {
48	  const s = sources[model];
49	  if (s !== undefined) return s;
50	  if (!asked.has(model)) {
51	    asked.add(model);
52	    const g = gen;
53	    const done = (r: StRigSource | null) => { if (g === gen) sources[model] = r; };
54	    try { loader(model).then(done, () => done(null)); } catch { done(null); }
55	  }
56	  return null;
57	}
58	
59	/* Gỡ nhân vật thật của slot i (đổi chủ, đổi mô hình, rời chế độ) */
60	function stDrop(i: number): void {
61	  const s = slots[i];
62	  if (!s.rig) return;
63	  s.rig.dispose(); s.rig = null; s.model = -1;
64	}
65	
66	/* Đặt slot i theo s.st: nhân vật thật nếu mô hình đã có, không thì hình khối. speed (m/s) chọn đoạn / nhịp bước, dt (s) cho mixer */
67	function stPlace(i: number, speed: number, dt: number): void {
68	  const s = slots[i];
69	  if (!group) return;
70	  if (!s.live) { stBlocky.place(i, null, 0); if (s.rig) s.rig.root.visible = false; return; }
71	  const model = stModelFor(i, s.who === 1);
72	  if (s.rig && s.model !== model) stDrop(i);
73	  if (!s.rig) {
74	    const src = stNeed(model);
75	    if (src) { s.rig = new StRig(src); s.model = model; group.add(s.rig.root); }
76	  }
77	  const t = s.st;
78	  if (!s.rig) { stBlocky.place(i, t, speed); return; }
79	  stBlocky.place(i, null, 0);
80	  const r = s.rig.root;
81	  r.visible = true;
82	  r.position.set(t.x, t.y, t.z); r.rotation.set(0, t.yaw, 0);   // mô hình hướng +X như hình khối: yaw quanh Y
83	  s.rig.pose(t.pose, speed, dt);
84	}
85	
86	function stHide(i: number): void {
87	  const s = slots[i];
88	  s.track.reset(); s.live = false;
89	  stDrop(i);
90	  stPlace(i, 0, 0);
91	}
92	
93	function stRefreshVisible(): void {
94	  if (!group) return;
95	  let any = false;
96	  for (const s of slots) if (s.live) { any = true; break; }
97	  group.visible = any;
98	  stBlocky.refresh();
99	}
100	
101	/* Tốc độ danh định theo dáng cho người khác (gói vị trí không có tốc độ) */
102	const stPoseSpeed = (pose: number) => (pose === ST_POSE_RUN ? C.run : pose === ST_POSE_WALK ? C.walk : 0);
103	
104	export const stAvatars = {
105	  get mesh(): THREE.Group | null { return group; },
106	  get self(): number { return me; },   // slot nhân vật của mình, -1 nếu không có (nhãn tên bỏ qua slot này)
107	
108	  /* Dựng lần đầu gọi (lười, ngoài thứ tự dựng cảnh), các lần sau trả lại nhóm cũ. Bên gọi thêm vào scene */
109	  build(): THREE.Group {
110	    if (group) return group;
111	    group = new THREE.Group();
112	    group.name = 'stroll-people';
113	    group.add(stBlocky.build());
114	    group.visible = false;
115	    return group;
116	  },
117	
118	  /* Bắt đầu nạp mô hình (mặc định 0, nhân vật của mình) trước khi cần, vd. lúc chọn thẻ Đi dạo. Không ném */
119	  preload(model = 0): void { stNeed(model); },
120	
121	  /* Nhân vật của mình ở slot (đi một mình: 0); s = null thì bỏ hiện slot đó. dt (s): bước chuyển động vừa chạy, cho mixer */
122	  setSelf(slot: number, s: StState | null, dt = 0): void {
123	    if (s === null) {
124	      if (me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
125	      me = -1; stRefreshVisible(); return;
126	    }
127	    const x = slots[slot];
128	    if (!x) return;
129	    if (me !== slot && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
130	    if (x.who !== 1) stDrop(slot);   // slot vừa thành của mình: bản sao người khác (nếu còn) bỏ
131	    me = slot; x.who = 1; x.track.reset();
132	    const t = x.st;
133	    t.x = s.x; t.y = s.y; t.z = s.z; t.yaw = s.yaw; t.pose = s.pose;
134	    x.live = true;
135	    stPlace(slot, s.speed, dt);
136	    stRefreshVisible();
137	  },
138	
139	  /* Danh sách người đi dạo đổi (sảnh, vào, ra): slot đổi chủ thì xóa mẫu, ẩn tới mẫu đầu; slot trống thì ẩn. Slot của mình do setSelf lo */
140	  sync(walkers: Flyer[], mySlot: number): void {
141	    if (mySlot !== me && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); me = -1; }   // đổi slot của mình: setSelf sẽ đặt lại
142	    for (let i = 0; i < N; i++) {
143	      const s = slots[i];
144	      let name: string | null = null;
145	      for (const w of walkers) if (w.slot === i) { name = w.name; break; }
146	      if (i === mySlot) { s.name = name; if (s.who === 2) { s.who = 0; stHide(i); } continue; }   // slot vừa thành của mình: bỏ người khác cũ, chờ setSelf
147	      if (name === null) { s.name = null; if (s.who === 2) { s.who = 0; stHide(i); } continue; }
148	      if (name !== s.name || s.who !== 2) { s.name = name; s.who = 2; stHide(i); }
149	    }
150	    stRefreshVisible();
151	  },
152	
153	  /* Gói vị trí gộp: w = [slot, x, y, z, yaw, pose, giờ gửi?]; chỉ nhận slot người khác đã biết chủ */
154	  onPos(w: number[][], nowMs: number): void {
155	    for (const e of w) {
156	      const i = e[0], s = slots[i];
157	      if (!s || i === me || s.who !== 2) continue;
158	      s.track.feed(e, nowMs, M);
159	    }
160	  },
161	
162	  /* Mỗi khung: đặt người khác theo mẫu nội suy (pose bậc thang); dt mixer = hiệu nowMs giữa hai lần gọi (StRig kẹp dtMax) */
163	  update(nowMs: number): void {
164	    const dt = lastNow < 0 ? 0 : (nowMs - lastNow) / 1000;
165	    lastNow = nowMs;
166	    const t = nowMs - M.interpSends * 1000 / M.sendHz;
167	    for (let i = 0; i < N; i++) {
168	      const s = slots[i];
169	      if (s.who !== 2) continue;
170	      if (!s.track.sample(t, s.pose, true)) { if (s.live) { s.live = false; stPlace(i, 0, 0); } continue; }
171	      const p = s.pose, st = s.st;
172	      st.x = p.x; st.y = p.y; st.z = p.z; st.yaw = p.yaw; st.pose = Math.round(p.bank);
173	      s.live = true;
174	      stPlace(i, stPoseSpeed(st.pose), dt);
175	    }
176	    stRefreshVisible();
177	  },
178	
179	  /* Trạng thái đang hiện của slot (cho nhãn tên, camera dù lượn); null nếu trống hoặc chưa có mẫu */
180	  slotState(slot: number): { x: number; y: number; z: number; yaw: number; pose: number } | null {
181	    const s = slots[slot];
182	    return s && s.live ? s.st : null;
183	  },
184	
185	  /* Tên người ở slot (theo sync, cả slot của mình); null nếu trống hoặc đi một mình */
186	  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },
187	
188	  /* Rời chế độ / rời phòng: gỡ hết nhân vật thật, ẩn hình khối, quên tên (nhóm và bộ đệm mô hình giữ lại để tái dùng) */
189	  clear(): void {
190	    me = -1; lastNow = -1;
191	    for (let i = 0; i < N; i++) { const s = slots[i]; s.who = 0; s.name = null; stHide(i); }
192	    stRefreshVisible();
193	  },
194	
195	  /* Cho test (stroll-check, multi-check): slot trống → null; real = đang hiện bằng nhân vật có xương; mix = trọng số ST_CLIPS đang dùng */
196	  debug(slot: number): { model: number; real: boolean; mix: number[]; rate: number } | null {
197	    const s = slots[slot];
198	    if (!s || s.who === 0) return null;
199	    const r = s.rig, real = !!r && s.live && r.root.visible;
200	    return { model: r ? s.model : stModelFor(slot, s.who === 1), real, mix: r ? Array.from(r.w) : [], rate: r ? r.rate : 0 };
201	  },
202	
203	  /* Chỉ dùng trong unit test: thay bộ nạp (null = stRigLoad thật) và quên bộ đệm mô hình */
204	  __setLoader(fn: ((model: number) => Promise<StRigSource | null>) | null): void {
205	    loader = fn || stRigLoad; gen++;
206	    sources = []; asked = new Set();
207	  }
208	};
