1	import * as THREE from 'three';
2	import { renderer, scene, camera } from './renderer';
3	import { composer } from './postprocessing';
4	
5	/* =====================================================================
6	   BIÊN DỊCH TRƯỚC (D-018) — chạy một lần lúc màn hình chờ còn hiện, trước khung hình đầu.
7	   Nếu không, three biên dịch shader của một vật liệu lần đầu nó được vẽ (đồng bộ trên luồng chính) ⇒ giật khi:
8	   chuyển đêm lần đầu (composer vẽ vào render target ⇒ biến thể không tone mapping), bay tới công trình có `details` đang ẩn, mặt cắt Hầm…
9	   - renderer.compile() duyệt MỌI object (kể cả đang ẩn), nên không cần bật tạm `visible`.
10	   - Hai biến thể: vẽ thẳng ra canvas (ban ngày) và vào render target (composer ban đêm; cũng trùng biến thể phản chiếu mặt nước).
11	   - Upload sẵn mọi texture (atlas quảng cáo 2048², địa chất 4096×636…) để lần hiện đầu không phải tải lên GPU.
12	   - Vẽ composer một lần: biên dịch các pass bloom / output.
13	   Biến thể vẽ bóng (MeshDepthMaterial) vẫn biên dịch lười khi vật đổ bóng vào khung bóng lần đầu (ít program, rẻ).
14	   ===================================================================== */
15	const wait = (ms: number) => new Promise<void>((ok) => setTimeout(ok, ms));
16	
17	export async function prewarm() {
18	  // Font chữ Việt: atlas quảng cáo vẽ lại khi font nạp xong — chờ trước để chỉ upload một lần (tối đa 3 s nếu không có mạng)
19	  if (document.fonts?.ready) await Promise.race([document.fonts.ready, wait(3000)]);
20	  const rt = renderer.getRenderTarget();
21	  renderer.setRenderTarget(null);
22	  const canvasPass = renderer.compileAsync(scene, camera);
23	  renderer.setRenderTarget(rt);
24	  await canvasPass;
25	  renderer.setRenderTarget(composer.readBuffer);
26	  const rtPass = renderer.compileAsync(scene, camera);
27	  renderer.setRenderTarget(rt);
28	  await rtPass;
29	  const seen = new Set<THREE.Texture>();
30	  scene.traverse((o) => {
31	    const m = (o as THREE.Mesh).material;
32	    if (!m) return;
33	    for (const mat of Array.isArray(m) ? m : [m]) for (const v of Object.values(mat)) if ((v as THREE.Texture)?.isTexture && !seen.has(v as THREE.Texture)) { seen.add(v as THREE.Texture); renderer.initTexture(v as THREE.Texture); }
34	  });
35	  // Vẽ thật một lần với MỌI object tạm hiện, không cắt theo khung nhìn, mọi level LOD, InstancedMesh rỗng có 1 instance:
36	  // upload hình học lên GPU, biên dịch biến thể vẽ bóng (MeshDepthMaterial) và phần trình điều khiển biên dịch lười lúc vẽ lần đầu
37	  // (đo GĐ1: không còn program mới nhưng lần đầu bay tới Thuận Phước / Hầm / Vòng quay vẫn khựng 3–5 s trên SwiftShader). Trả nguyên trạng ngay sau đó.
38	  const saved: [THREE.Object3D, boolean, boolean][] = [], counts: [THREE.InstancedMesh, number][] = [], lods: THREE.LOD[] = [];
