let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
export function stRigSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
async function stRigWarm(o: THREE.Object3D): Promise<void> {
  if (!warm) return;
